import bisect

def solve(nums, k):
    min_val = min(nums)
    max_val = max(nums)

    def count_less_equal(val):
        return bisect.bisect_right(nums, val)

    left, right = min_val, max_val
    while left < right:
        mid = (left + right) // 2
        cnt = count_less_equal(mid)
        if cnt < k:
            left = mid + 1
        else:
            right = mid
    return left
