def solve(grid, start, goal):
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        return []
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    stack = [(start[0], start[1])]
    visited[start[0]][start[1]] = True
    path = {start: [start]}

    while stack:
        r, c = stack[-1]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == '.':
                visited[nr][nc] = True
                path[(nr, nc)] = path[(r, c)] + [(nr, nc)]
                stack.append((nr, nc))
                if (nr, nc) == goal:
                    return path[(nr, nc)]
        if stack and not any((nr, nc) == goal for nr, nc in stack):
            stack.pop()
            if stack:
                del path[stack[-1]]
    return []
