def solve(grid, start, goal):
    if not grid or not grid[0] or start == goal:
        if is_free(grid, start) and is_free(grid, goal):
            return [start]
        else:
            return []

    start_row, start_col = start
    goal_row, goal_col = goal

    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_free(grid, pos):
        row, col = pos
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def bfs(start, target):
        from collections import deque
        visited = set()
        queue = deque([(start, [start])])
        visited.add(start)
        while queue:
            pos, path = queue.popleft()
            if pos == target:
                return path
            for dr, dc in directions:
                r, c = pos[0] + dr, pos[1] + dc
                if is_free(grid, (r, c)) and (r, c) not in visited:
                    visited.add((r, c))
                    queue.append(((r, c), path + [(r, c)]))
        return []

    forward_path = bfs(start, goal)
    if forward_path:
        return forward_path

    reverse_path = bfs(goal, start)
    if reverse_path:
        return reverse_path[::-1]

    return []
