import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    priority_queue = []
    heapq.heappush(priority_queue, (0, heuristic(start, goal), start, [start]))
    visited = set()

    while priority_queue:
        _, _, current, path = heapq.heappop(priority_queue)
        row, col = current

        if current == goal:
            return path

        if current in visited:
            continue

        visited.add(current)

        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                new_path = path + [(nr, nc)]
                priority = len(new_path) + heuristic((nr, nc), goal)
                heapq.heappush(priority_queue, (priority, heuristic((nr, nc), goal), (nr, nc), new_path))

    return []
