def solve(nums, k):
    def _introselect(arr, k):
        def _partition(arr, low, high):
            pivot = random.choice(arr[low:high+1])
            left, mid, right = [], [], []
            for num in arr:
                if num < pivot:
                    left.append(num)
                elif num == pivot:
                    mid.append(num)
                else:
                    right.append(num)
            return left + mid + right

        def _select(arr, k):
            if len(arr) <= 1:
                return arr[0]
            if k <= len(arr) // 2:
                return _select(_partition(arr, 0, len(arr)-1), k)
            else:
                return _select(_partition(arr, 0, len(arr)-1), k - len(arr) // 2 - 1)

        def _median_of_medians(arr):
            if len(arr) <= 5:
                return sorted(arr)[len(arr)//2]
            medians = []
            for i in range(0, len(arr), 5):
                medians.append(_median_of_medians(sorted(arr[i:i+5])))
            return _median_of_medians(medians)

        def _introselect_helper(arr, k):
            if len(arr) <= 12:
                return sorted(arr)[k-1]
            pivot = _median_of_medians(arr)
            left, mid, right = [], [], []
            for num in arr:
                if num < pivot:
                    left.append(num)
                elif num == pivot:
                    mid.append(num)
                else:
                    right.append(num)
            if k <= len(left):
                return _introselect_helper(left, k)
            elif k <= len(left) + len(mid):
                return pivot
            else:
                return _introselect_helper(right, k - len(left) - len(mid))

        return _introselect_helper(nums, k)

    return solve(nums, k)
