        if in_degree[i] == 0:
            queue.append(i)

    topo_order = []
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v, _ in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # If topological sort does not include all nodes, the graph has a cycle
    if len(topo_order) != n:
        return -1

    # Step 2: Relax edges in topological order
    dist = [float('inf')] * n
    dist[s] = 0

    for u in topo_order:
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    return dist[t] if dist[t] != float('inf') else -1
