        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = current[0] + dr, current[1] + dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                path.append((nr, nc))
                if dfs((nr, nc), depth + 1, max_depth, path):
                    return True
                path.pop()
        return False

    max_depth = 0
    path = [start]
    while True:
        if dfs(start, 1, max_depth, path):
