def solve(grid, start, goal):
    if not grid or start == goal:
        start_row, start_col = start
        if grid[start_row][start_col] == '#':
            return []
        return [start]

    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def dfs(current, depth, max_depth, path, visited):
        if depth > max_depth:
            return False
        row, col = current
        if row == goal_row and col == goal_col:
            path.append(current)
            return True
        visited.add((row, col))
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                path.append((nr, nc))
                if dfs((nr, nc), depth + 1, max_depth, path, visited):
                    return True
                path.pop()
        visited.remove((row, col))
        return False

    max_depth = 0
    while True:
        path = [start]
        visited = set([start])
        if dfs(start, 1, max_depth, path, visited):
            return path
        max_depth += 1
