from heapq import heappush, heappop

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if not (0 <= start[0] < rows and 0 <= start[1] < cols or 0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue: (heuristic, current position, path)
    queue = [(manhattan(start, goal), start, [start])]
    visited = set()
    visited.add(start)

    while queue:
        _, current, path = heappop(queue)
        row, col = current
        if current == goal:
            return path
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                visited.add((nr, nc))
                new_path = path + [(nr, nc)]
                heappush(queue, (manhattan((nr, nc), goal), (nr, nc), new_path))

    return []

def manhattan(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])
