def solve(nums, k):
    nums = nums.copy()
    left, right = 0, len(nums) - 1
    while left <= right:
        pivot = nums[right]
        i = left
        for j in range(left, right):
            if nums[j] < pivot:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
        nums[i], nums[right] = nums[right], nums[i]
        if i == k - 1:
            return nums[i]
        elif i < k - 1:
            left = i + 1
        else:
            right = i - 1
    return nums[k - 1]
