def solve(nums, target):
    nums = [(val, i) for i, val in enumerate(nums)]
    nums.sort()
    for i in range(len(nums)):
        complement = target - nums[i][0]
        left, right = i + 1, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid][0] == complement:
                return [nums[i][1], nums[mid][1]] if nums[i][1] < nums[mid][1] else [nums[mid][1], nums[i][1]]
            elif nums[mid][0] < complement:
                left = mid + 1
            else:
                right = mid - 1
